import subprocess

formats = ["yj", "yy", "yt", "yc", "tj", "ty", "tt", "tc", "jj", "jy", "jt", "jc", "cy", "ct", "cj", "cc"]
flags = ["i", "e", "k", "n"]

for fmt in formats:
    for flg in flags:
        cmd = [f"-{fmt}", f"-{flg}"]
