{"command":"python3 -c '
import subprocess, json

test_data = {
    "str": "hello world",
    "int": 42,
    "float": 3.14159,
    "bool_t": True,
    "bool_f": False,
    "null": None,
    "list": [1, "a", True, None],
    "nested": {
        "x": 10,
        "y": [20, 30]
    }
}

json_str = json.dumps(test_data)

for flg in ["-jj", "-jy", "-jt", "-jc", "-yj", "-yy", "-yt", "-yc", "-tj", "-ty", "-tt", "-tc", "-cj", "-cy", "-ct", "-cc"]:
    p = subprocess.run(["./executable", flg], input=json_str.encode() if "j" in flg[:2] else b"", stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    print(f"=== {flg} ===")
    if p.returncode == 0:
        print(f"STDOUT:\n{p.stdout.decode()}")
    else:
        print(f"ERR: {p.stderr.decode()}")
'"}

