{"command":"cd /tmp/gotest
cat << 'EOF' > main.go
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"gopkg.in/yaml.v3"
)

type MapItem struct {
	Key   interface{}
	Value interface{}
}

type OrderedMap []MapItem

func (m OrderedMap) MarshalJSON() ([]byte, error) {
	var buf bytes.Buffer
	buf.WriteByte('{')
	for i, item := range m {
		if i > 0 {
			buf.WriteByte(',')
		}
		kB, err := json.Marshal(item.Key)
		if err != nil {
			return nil, err
		}
		buf.Write(kB)
		buf.WriteByte(':')
		vB, err := json.Marshal(item.Value)
		if err != nil {
			return nil, err
		}
		buf.Write(vB)
	}
	buf.WriteByte('}')
	return buf.Bytes(), nil
}

func nodeToValue(n *yaml.Node) interface{} {
	if n == nil {
		return nil
	}
	switch n.Kind {
	case yaml.DocumentNode:
		if len(n.Content) > 0 {
			return nodeToValue(n.Content[0])
		}
		return nil
	case yaml.MappingNode:
		om := make(OrderedMap, 0, len(n.Content)/2)
		for i := 0; i < len(n.Content); i += 2 {
			k := nodeToValue(n.Content[i])
			v := nodeToValue(n.Content[i+1])
			om = append(om, MapItem{Key: k, Value: v})
		}
		return om
	case yaml.SequenceNode:
		arr := make([]interface{}, 0, len(n.Content))
		for _, child := range n.Content {
			arr = append(arr, nodeToValue(child))
		}
		return arr
	case yaml.ScalarNode:
		var val interface{}
		n.Decode(&val)
		return val
	default:
		return nil
	}
}

func main() {
	yamlStr := "z: 1\na: 2\nm: 3\n"
	var node yaml.Node
	yaml.Unmarshal([]byte(yamlStr), &node)

	val := nodeToValue(&node)
	b, err := json.Marshal(val)
	fmt.Println("err:", err)
	fmt.Println("json:", string(b))
}
EOF
GOMODCACHE=/usr/local/go/mod-cache go build -mod=readonly . 2>&1
./test"}

