package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"github.com/BurntSushi/toml"
)

type MapItem struct {
	Key   interface{}
	Value interface{}
}

type OrderedMap []MapItem

func (m OrderedMap) MarshalJSON() ([]byte, error) {
	var buf bytes.Buffer
	buf.WriteByte('{')
	for i, item := range m {
		if i > 0 {
			buf.WriteByte(',')
		}
		kB, err := json.Marshal(fmt.Sprint(item.Key))
		if err != nil {
			return nil, err
		}
		buf.Write(kB)
		buf.WriteByte(':')
		vB, err := json.Marshal(item.Value)
		if err != nil {
			return nil, err
		}
		buf.Write(vB)
	}
	buf.WriteByte('}')
	return buf.Bytes(), nil
}

func orderMap(val interface{}, keys []toml.Key) interface{} {
	switch v := val.(type) {
	case map[string]interface{}:
		// Find order of top-level keys for this map
		// ...
		om := make(OrderedMap, 0)
		// gather keys in order
		seen := make(map[string]bool)
		for _, k := range keys {
			if len(k) > 0 {
				topKey := k[0]
				if !seen[topKey] {
					seen[topKey] = true
					if childVal, ok := v[topKey]; ok {
						// filter subkeys
						var subKeys []toml.Key
						for _, sk := range keys {
							if len(sk) > 1 && sk[0] == topKey {
								subKeys = append(subKeys, sk[1:])
							}
						}
						om = append(om, MapItem{
							Key:   topKey,
							Value: orderMap(childVal, subKeys),
						})
					}
				}
			}
		}
		return om
	case []interface{}:
		arr := make([]interface{}, len(v))
		for i, elem := range v {
			arr[i] = orderMap(elem, keys)
		}
		return arr
	default:
		return v
	}
}

func main() {
	tomlStr := `
z = 1
[server]
port = 8080
host = "127.0.0.1"

[database]
user = "root"
pass = "secret"
`
	var val interface{}
	md, err := toml.Decode(tomlStr, &val)
	fmt.Println("err:", err)
	om := orderMap(val, md.Keys())
	b, _ := json.Marshal(om)
	fmt.Println("ordered json:", string(b))
}
EOF
