	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	return parseJSONToken(tok, dec)
}

func parseJSONToken(tok json.Token, dec *json.Decoder) (interface{}, error) {
	switch v := tok.(type) {
	case json.Delim:
		if v == '{' {
			var om OrderedMap
			for dec.More() {
				keyTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				keyStr, ok := keyTok.(string)
				if !ok {
					return nil, fmt.Errorf("expected string key in map")
				}
				val, err := decodeJSONValue(dec)
				if err != nil {
					return nil, err
				}
				om = append(om, MapItem{Key: keyStr, Value: val})
			}
			_, err := dec.Token()
			if err != nil {
				return nil, err
			}
			return om, nil
		} else if v == '[' {
			var arr []interface{}
			for dec.More() {
				val, err := decodeJSONValue(dec)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			_, err := dec.Token()
			if err != nil {
				return nil, err
			}
			return arr, nil
		}
		return nil, fmt.Errorf("unexpected delim %v", v)
	case json.Number:
		if i, err := v.Int64(); err == nil {
			return i, nil
		}
		if f, err := v.Float64(); err == nil {
			return f, nil
		}
		return v.String(), nil
	case string, bool, nil:
		return v, nil
	default:
		return nil, fmt.Errorf("unexpected token %v", tok)
	}
