	om := OrderedMap{
		MapItem{Key: "z", Value: 1},
		MapItem{Key: "a", Value: []interface{}{"foo", "bar"}},
		MapItem{Key: "m", Value: OrderedMap{MapItem{Key: "nested", Value: true}}},
	}
	node := valueToYAMLNode(om)
	b, err := yaml.Marshal(node)
	fmt.Println("err:", err)
	fmt.Print(string(b))
