)

const usageFmt = `Usage: %s [-][ytjcrneikhv]

Convert between YAML, TOML, JSON, and HCL.
Preserves map order.

-x[x]  Convert using stdin. Valid options:
          -yj, -y = YAML to JSON (default)
          -yy     = YAML to YAML
          -yt     = YAML to TOML
          -yc     = YAML to HCL
          -tj, -t = TOML to JSON
          -ty     = TOML to YAML
          -tt     = TOML to TOML
          -tc     = TOML to HCL
          -jj     = JSON to JSON
          -jy, -r = JSON to YAML
          -jt     = JSON to TOML
          -jc     = JSON to HCL
          -cy     = HCL to YAML
          -ct     = HCL to TOML
          -cj, -c = HCL to JSON
          -cc     = HCL to HCL
-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)
-e     Escape HTML (JSON out only)
-i     Indent output (JSON or TOML out only)
-k     Attempt to parse keys as objects or numeric types (YAML out only)
-h     Show this help message
-v     Show version

`

type MapItem struct {
	Key   interface{}
	Value interface{}
}

type OrderedMap []MapItem

func (m OrderedMap) MarshalJSON() ([]byte, error) {
	var buf bytes.Buffer
	buf.WriteByte('{')
	for i, item := range m {
		if i > 0 {
			buf.WriteByte(',')
		}
		kB, err := json.Marshal(fmt.Sprint(item.Key))
		if err != nil {
			return nil, err
		}
		buf.Write(kB)
		buf.WriteByte(':')
		vB, err := json.Marshal(item.Value)
		if err != nil {
			return nil, err
		}
		buf.Write(vB)
	}
	buf.WriteByte('}')
	return buf.Bytes(), nil
}

func main() {
	var (
		showHelp           bool
		showVersion        bool
		doNotConvertInfNaN bool
		escapeHTML         bool
		indent             bool
		parseKeys          bool
		formatChars        []rune
		invalidFlags       []string
	)

	for _, arg := range os.Args[1:] {
		s := arg
		if strings.HasPrefix(s, "-") {
			s = strings.TrimLeft(s, "-")
		}
		for _, ch := range s {
			switch ch {
			case 'y', 't', 'j', 'c':
				formatChars = append(formatChars, ch)
			case 'r':
				formatChars = append(formatChars, 'j', 'y')
			case 'n':
				doNotConvertInfNaN = true
			case 'e':
				escapeHTML = true
			case 'i':
				indent = true
			case 'k':
				parseKeys = true
			case 'h':
				showHelp = true
			case 'v':
				showVersion = true
			default:
				invalidFlags = append(invalidFlags, string(ch))
			}
		}
	}

	if showHelp {
		fmt.Printf(usageFmt, os.Args[0])
		os.Exit(0)
	}
	if showVersion {
		fmt.Println("v0.0.0")
		os.Exit(0)
	}

	if len(invalidFlags) > 0 {
		fmt.Fprintf(os.Stderr, usageFmt, os.Args[0])
		fmt.Fprintf(os.Stderr, "Error: invalid flags specified: %s\n", strings.Join(invalidFlags, " "))
		os.Exit(1)
	}

	inFmt := "yaml"
	outFmt := "json"

	if len(formatChars) == 1 {
		switch formatChars[0] {
		case 'y':
			inFmt = "yaml"
			outFmt = "json"
		case 't':
			inFmt = "toml"
			outFmt = "json"
		case 'j':
			inFmt = "json"
			outFmt = "json"
		case 'c':
			inFmt = "hcl"
			outFmt = "json"
		}
	} else if len(formatChars) >= 2 {
		c1 := formatChars[len(formatChars)-2]
		c2 := formatChars[len(formatChars)-1]
		charToFmt := map[rune]string{'y': "yaml", 't': "toml", 'j': "json", 'c': "hcl"}
		inFmt = charToFmt[c1]
		outFmt = charToFmt[c2]
	}

	if escapeHTML && outFmt != "json" {
		fmt.Fprintf(os.Stderr, usageFmt, os.Args[0])
		fmt.Fprintln(os.Stderr, "Error: flag -e only valid for JSON output")
		os.Exit(1)
	}
	if parseKeys && outFmt != "yaml" {
		fmt.Fprintf(os.Stderr, usageFmt, os.Args[0])
		fmt.Fprintln(os.Stderr, "Error: flag -k only valid for YAML output")
		os.Exit(1)
	}
	if indent && outFmt != "json" && outFmt != "toml" {
		fmt.Fprintf(os.Stderr, usageFmt, os.Args[0])
		fmt.Fprintln(os.Stderr, "Error: flag -i only valid for JSON or TOML output")
		os.Exit(1)
	}

	inputBytes, err := io.ReadAll(os.Stdin)
	if err != nil {
		os.Exit(1)
	}

	if len(bytes.TrimSpace(inputBytes)) == 0 {
		if inFmt == "yaml" {
			os.Exit(0)
		} else if inFmt == "toml" || inFmt == "hcl" {
			if outFmt == "json" || outFmt == "yaml" {
				fmt.Println("{}")
			}
			os.Exit(0)
		}
	}

	var data interface{}

	switch inFmt {
	case "json":
		var dummy interface{}
		if err := json.Unmarshal(inputBytes, &dummy); err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing JSON: %v\n", err)
			os.Exit(1)
		}
		data, _ = decodeJSONOrdered(inputBytes)
	case "yaml":
		var node yaml.Node
		if err := yaml.Unmarshal(inputBytes, &node); err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing YAML: %v\n", err)
			os.Exit(1)
		}
		data = yamlNodeToValue(&node)
	case "toml":
		var rawVal interface{}
		md, err := toml.Decode(string(inputBytes), &rawVal)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing TOML: %v\n", err)
			os.Exit(1)
		}
		data = orderTOMLMap(rawVal, md.Keys())
	case "hcl":
		parser := NewHCLParser(string(inputBytes))
		om, err := parser.parseBody()
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing HCL: %v\n", err)
			os.Exit(1)
		}
		data = om
	}

	if !doNotConvertInfNaN {
		if inFmt == "json" && (outFmt == "yaml" || outFmt == "toml") {
			data = convertStringsToInfNaN(data)
		} else if (inFmt == "yaml" || inFmt == "toml") && outFmt == "json" {
			data = convertInfNaNToStrings(data)
		}
	} else if outFmt == "json" {
		data = handleInfNaNForJSON(data)
	}

	if parseKeys && outFmt == "yaml" {
		data = parseKeysInMap(data)
	}

	switch outFmt {
	case "json":
		if data == nil {
			os.Exit(0)
		}
		var buf bytes.Buffer
		enc := json.NewEncoder(&buf)
		enc.SetEscapeHTML(escapeHTML)
		if indent {
			enc.SetIndent("", "  ")
		}
		if err := enc.Encode(data); err != nil {
			fmt.Fprintf(os.Stderr, "Error writing JSON: %v\n", err)
			os.Exit(1)
		}
		os.Stdout.Write(buf.Bytes())
	case "yaml":
		if data == nil {
			os.Exit(0)
		}
		node := valueToYAMLNode(data)
		var buf bytes.Buffer
		enc := yaml.NewEncoder(&buf)
		enc.SetIndent(2)
		if err := enc.Encode(node); err != nil {
			fmt.Fprintf(os.Stderr, "Error writing YAML: %v\n", err)
			os.Exit(1)
		}
		os.Stdout.Write(buf.Bytes())
	case "toml":
		if data == nil {
			os.Exit(0)
		}
		var buf bytes.Buffer
		if err := writeTOML(&buf, data, indent); err != nil {
			fmt.Fprintf(os.Stderr, "Error writing TOML: %v\n", err)
			os.Exit(1)
		}
		os.Stdout.Write(buf.Bytes())
	case "hcl":
		if data == nil {
			os.Exit(0)
		}
		var buf bytes.Buffer
		if err := writeHCL(&buf, data); err != nil {
			fmt.Fprintf(os.Stderr, "Error writing HCL: %v\n", err)
			os.Exit(1)
		}
		os.Stdout.Write(buf.Bytes())
	}
}

func decodeJSONOrdered(data []byte) (interface{}, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	return decodeJSONValue(dec)
}

func decodeJSONValue(dec *json.Decoder) (interface{}, error) {
	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	return parseJSONToken(tok, dec)
}

func parseJSONToken(tok json.Token, dec *json.Decoder) (interface{}, error) {
	switch v := tok.(type) {
	case json.Delim:
		if v == '{' {
			var om OrderedMap
			for dec.More() {
				keyTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				keyStr := fmt.Sprint(keyTok)
				val, err := decodeJSONValue(dec)
				if err != nil {
					return nil, err
				}
				om = append(om, MapItem{Key: keyStr, Value: val})
			}
			dec.Token()
			return om, nil
		} else if v == '[' {
			var arr []interface{}
			for dec.More() {
				val, err := decodeJSONValue(dec)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			dec.Token()
			return arr, nil
		}
		return nil, fmt.Errorf("unexpected delim %v", v)
	case json.Number:
		if i, err := v.Int64(); err == nil {
			return i, nil
		}
		if f, err := v.Float64(); err == nil {
			return f, nil
		}
		return v.String(), nil
	case string, bool, nil:
		return v, nil
	default:
		return nil, fmt.Errorf("unexpected token %v", tok)
	}
}

func yamlNodeToValue(n *yaml.Node) interface{} {
	if n == nil {
		return nil
	}
	switch n.Kind {
	case yaml.DocumentNode:
		if len(n.Content) > 0 {
			return yamlNodeToValue(n.Content[0])
		}
		return nil
	case yaml.MappingNode:
		om := make(OrderedMap, 0, len(n.Content)/2)
		for i := 0; i < len(n.Content); i += 2 {
			k := yamlNodeToValue(n.Content[i])
			v := yamlNodeToValue(n.Content[i+1])
			om = append(om, MapItem{Key: k, Value: v})
		}
		return om
	case yaml.SequenceNode:
		arr := make([]interface{}, 0, len(n.Content))
		for _, child := range n.Content {
			arr = append(arr, yamlNodeToValue(child))
		}
		return arr
	case yaml.ScalarNode:
		var val interface{}
		n.Decode(&val)
		return val
	default:
		return nil
	}
}

func valueToYAMLNode(v interface{}) *yaml.Node {
	if v == nil {
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!null", Value: "null"}
	}
	switch val := v.(type) {
	case OrderedMap:
		content := make([]*yaml.Node, 0, len(val)*2)
		for _, item := range val {
			kNode := valueToYAMLNode(item.Key)
			vNode := valueToYAMLNode(item.Value)
			content = append(content, kNode, vNode)
		}
		return &yaml.Node{Kind: yaml.MappingNode, Content: content, Tag: "!!map"}
	case []interface{}:
		content := make([]*yaml.Node, 0, len(val))
		for _, elem := range val {
			content = append(content, valueToYAMLNode(elem))
		}
		return &yaml.Node{Kind: yaml.SequenceNode, Content: content, Tag: "!!seq"}
	default:
		var node yaml.Node
		b, _ := yaml.Marshal(val)
		yaml.Unmarshal(b, &node)
		if node.Kind == yaml.DocumentNode && len(node.Content) > 0 {
			return node.Content[0]
		}
		return &node
	}
}

func orderTOMLMap(val interface{}, keys []toml.Key) interface{} {
	switch v := val.(type) {
	case map[string]interface{}:
		om := make(OrderedMap, 0)
		seen := make(map[string]bool)
		for _, k := range keys {
			if len(k) > 0 {
				topKey := k[0]
				if !seen[topKey] {
					seen[topKey] = true
					if childVal, ok := v[topKey]; ok {
						var subKeys []toml.Key
						for _, sk := range keys {
							if len(sk) > 1 && sk[0] == topKey {
								subKeys = append(subKeys, sk[1:])
							}
						}
						om = append(om, MapItem{
							Key:   topKey,
							Value: orderTOMLMap(childVal, subKeys),
						})
					}
				}
			}
		}
		for k, childVal := range v {
			if !seen[k] {
				seen[k] = true
				om = append(om, MapItem{
					Key:   k,
					Value: orderTOMLMap(childVal, nil),
				})
			}
		}
		return om
	case []interface{}:
		arr := make([]interface{}, len(v))
		for i, elem := range v {
			arr[i] = orderTOMLMap(elem, keys)
		}
		return arr
	default:
		return v
	}
}

func isScalarOrScalarArray(v interface{}) bool {
	switch val := v.(type) {
	case OrderedMap:
		return false
	case []interface{}:
		return !isArrayOfMaps(val)
	default:
		return true
	}
}

func isArrayOfMaps(arr []interface{}) bool {
	if len(arr) == 0 {
		return false
	}
	for _, elem := range arr {
		if _, ok := elem.(OrderedMap); ok {
			return true
		}
	}
	return false
}

func formatTOMLValue(v interface{}) (string, error) {
	if v == nil {
		return "", fmt.Errorf("nil not supported in TOML")
	}
	switch val := v.(type) {
	case string:
		b, _ := json.Marshal(val)
		return string(b), nil
	case bool:
		if val {
			return "true", nil
		}
		return "false", nil
	case int:
		return strconv.Itoa(val), nil
	case int64:
		return strconv.FormatInt(val, 10), nil
	case float64:
		if math.IsInf(val, 1) {
			return "+inf", nil
		}
		if math.IsInf(val, -1) {
			return "-inf", nil
		}
		if math.IsNaN(val) {
			return "nan", nil
		}
		s := strconv.FormatFloat(val, 'f', -1, 64)
		if !strings.Contains(s, ".") {
			s += ".0"
		}
		return s, nil
	case []interface{}:
		var parts []string
		for _, elem := range val {
			if elem == nil {
				continue
			}
			s, err := formatTOMLValue(elem)
			if err != nil {
				return "", err
			}
			parts = append(parts, s)
		}
		return "[" + strings.Join(parts, ", ") + "]", nil
	default:
		return fmt.Sprint(val), nil
	}
}

func writeTOML(w io.Writer, val interface{}, useIndent bool) error {
	indentStr := ""
	if useIndent {
		indentStr = "  "
	}
	return writeTOMLTable(w, "", val, indentStr, 0, true)
}

func writeTOMLTable(w io.Writer, prefix string, val interface{}, indentStr string, depth int, isTopLevel bool) error {
	om, ok := val.(OrderedMap)
	if !ok {
		return fmt.Errorf("expected map for TOML top-level")
	}

	currentIndent := ""
	if indentStr != "" {
		currentIndent = strings.Repeat(indentStr, depth)
	}

	for _, item := range om {
		key := fmt.Sprint(item.Key)
		if isScalarOrScalarArray(item.Value) {
			sVal, err := formatTOMLValue(item.Value)
			if err != nil {
				return err
			}
			fmt.Fprintf(w, "%s%s = %s\n", currentIndent, key, sVal)
		}
	}

	for _, item := range om {
		key := fmt.Sprint(item.Key)
		fullKey := key
		if prefix != "" {
			fullKey = prefix + "." + key
		}

		if subMap, isMap := item.Value.(OrderedMap); isMap {
			fmt.Fprintln(w)
			fmt.Fprintf(w, "%s[%s]\n", currentIndent, fullKey)
			writeTOMLTable(w, fullKey, subMap, indentStr, depth+1, false)
		} else if arr, isArr := item.Value.([]interface{}); isArr && isArrayOfMaps(arr) {
			for _, elem := range arr {
				fmt.Fprintln(w)
				fmt.Fprintf(w, "%s[[%s]]\n", currentIndent, fullKey)
				writeTOMLTable(w, fullKey, elem, indentStr, depth+1, false)
			}
		}
	}
	return nil
}

func writeHCL(w io.Writer, val interface{}) error {
	om, ok := val.(OrderedMap)
	if !ok {
		return fmt.Errorf("Expected object, got unknown token: 1:1 STRING")
	}
	var blocks []string
	for _, item := range om {
		key := fmt.Sprint(item.Key)
		hclStr, err := formatHCLItem(key, item.Value, 0)
		if err != nil {
			return err
		}
		blocks = append(blocks, hclStr)
	}
	fmt.Fprint(w, strings.Join(blocks, "\n\n"))
	return nil
}

func formatHCLItem(key string, val interface{}, depth int) (string, error) {
	quotedKey := fmt.Sprintf("%q", key)
	indentStr := strings.Repeat("  ", depth)

	if subMap, isMap := val.(OrderedMap); isMap {
		formattedMap, err := formatHCLBody(subMap, depth+1)
		if err != nil {
			return "", err
		}
		return fmt.Sprintf("%s%s = {\n%s\n%s}", indentStr, quotedKey, formattedMap, indentStr), nil
	}

	if arr, isArr := val.([]interface{}); isArr && isArrayOfMaps(arr) {
		var blocks []string
		for _, elem := range arr {
			s, err := formatHCLItem(key, elem, depth)
			if err != nil {
				return "", err
			}
			blocks = append(blocks, s)
		}
		return strings.Join(blocks, "\n\n"), nil
	}

	formattedVal, err := formatHCLValue(val)
	if err != nil {
		return "", err
	}
	return fmt.Sprintf("%s%s = %s", indentStr, quotedKey, formattedVal), nil
}

func formatHCLBody(om OrderedMap, depth int) (string, error) {
	var items []string
	indentStr := strings.Repeat("  ", depth)
	for _, item := range om {
		key := fmt.Sprint(item.Key)
		quotedKey := fmt.Sprintf("%q", key)
		if subMap, isMap := item.Value.(OrderedMap); isMap {
			body, err := formatHCLBody(subMap, depth+1)
			if err != nil {
				return "", err
			}
			items = append(items, fmt.Sprintf("%s%s = {\n%s\n%s}", indentStr, quotedKey, body, indentStr))
		} else {
			formattedVal, err := formatHCLValue(item.Value)
			if err != nil {
				return "", err
			}
			items = append(items, fmt.Sprintf("%s%s = %s", indentStr, quotedKey, formattedVal))
		}
	}
	return strings.Join(items, "\n\n"), nil
}

func formatHCLValue(v interface{}) (string, error) {
	if v == nil {
		return "", nil
	}
	switch val := v.(type) {
	case string:
		b, _ := json.Marshal(val)
		return string(b), nil
	case bool:
		if val {
			return "true", nil
		}
		return "false", nil
	case int:
		return strconv.Itoa(val), nil
	case int64:
		return strconv.FormatInt(val, 10), nil
	case float64:
		return strconv.FormatFloat(val, 'f', -1, 64), nil
	case []interface{}:
		var parts []string
		for _, elem := range val {
			if elem == nil {
				return "", fmt.Errorf("unexpected token while parsing list: NULL")
			}
			s, err := formatHCLValue(elem)
			if err != nil {
				return "", err
			}
			parts = append(parts, s)
		}
		return "[" + strings.Join(parts, ", ") + "]", nil
	default:
		return fmt.Sprint(val), nil
	}
}

type TokenType int

const (
	TokEOF TokenType = iota
	TokIdent
	TokString
	TokNumber
	TokSymbol
)

type Token struct {
	Type TokenType
	Val  string
	Line int
	Col  int
}

type HCLLexer struct {
	src  []rune
	pos  int
	line int
	col  int
}

func NewHCLLexer(input string) *HCLLexer {
	return &HCLLexer{src: []rune(input), pos: 0, line: 1, col: 1}
}

func (l *HCLLexer) NextToken() Token {
	l.skipWhitespaceAndComments()
	if l.pos >= len(l.src) {
		return Token{Type: TokEOF, Line: l.line, Col: l.col}
	}

	startLine, startCol := l.line, l.col
	ch := l.src[l.pos]

	if ch == '"' {
		return l.readString()
	}
	if ch == '<' && l.pos+1 < len(l.src) && l.src[l.pos+1] == '<' {
		return l.readHeredoc()
	}
	if isIdentStart(ch) {
		return l.readIdent()
	}
	if unicode.IsDigit(ch) || (ch == '-' && l.pos+1 < len(l.src) && unicode.IsDigit(l.src[l.pos+1])) {
		return l.readNumber()
	}

	l.advance()
	return Token{Type: TokSymbol, Val: string(ch), Line: startLine, Col: startCol}
}

func (l *HCLLexer) advance() rune {
	if l.pos >= len(l.src) {
		return 0
	}
	ch := l.src[l.pos]
	l.pos++
	if ch == '\n' {
		l.line++
		l.col = 1
	} else {
		l.col++
	}
	return ch
}

func (l *HCLLexer) peek() rune {
	if l.pos >= len(l.src) {
		return 0
	}
	return l.src[l.pos]
}

func (l *HCLLexer) skipWhitespaceAndComments() {
	for l.pos < len(l.src) {
		ch := l.src[l.pos]
		if unicode.IsSpace(ch) {
			l.advance()
			continue
		}
		if ch == '#' {
			for l.pos < len(l.src) && l.src[l.pos] != '\n' {
				l.advance()
			}
			continue
		}
		if ch == '/' && l.pos+1 < len(l.src) {
			next := l.src[l.pos+1]
			if next == '/' {
				for l.pos < len(l.src) && l.src[l.pos] != '\n' {
					l.advance()
				}
				continue
			}
			if next == '*' {
				l.advance()
				l.advance()
				for l.pos+1 < len(l.src) && !(l.src[l.pos] == '*' && l.src[l.pos+1] == '/') {
					l.advance()
				}
				if l.pos < len(l.src) {
					l.advance()
				}
				if l.pos < len(l.src) {
					l.advance()
				}
				continue
			}
		}
		break
	}
}

func isIdentStart(ch rune) bool {
	return unicode.IsLetter(ch) || ch == '_'
}

func isIdentPart(ch rune) bool {
	return unicode.IsLetter(ch) || unicode.IsDigit(ch) || ch == '_' || ch == '-' || ch == '.'
}

func (l *HCLLexer) readIdent() Token {
	startLine, startCol := l.line, l.col
	var sb strings.Builder
	for l.pos < len(l.src) && isIdentPart(l.src[l.pos]) {
		sb.WriteRune(l.advance())
	}
	return Token{Type: TokIdent, Val: sb.String(), Line: startLine, Col: startCol}
}

func (l *HCLLexer) readNumber() Token {
	startLine, startCol := l.line, l.col
	var sb strings.Builder
	if l.peek() == '-' {
		sb.WriteRune(l.advance())
	}
	for l.pos < len(l.src) && (unicode.IsDigit(l.src[l.pos]) || l.src[l.pos] == '.') {
		sb.WriteRune(l.advance())
	}
	return Token{Type: TokNumber, Val: sb.String(), Line: startLine, Col: startCol}
}

func (l *HCLLexer) readString() Token {
	startLine, startCol := l.line, l.col
	l.advance()
	var sb strings.Builder
	for l.pos < len(l.src) {
		ch := l.advance()
		if ch == '"' {
			break
		}
		if ch == '\\' && l.pos < len(l.src) {
			escaped := l.advance()
			switch escaped {
			case 'n':
				sb.WriteRune('\n')
			case 't':
				sb.WriteRune('\t')
			case 'r':
				sb.WriteRune('\r')
			case '"':
				sb.WriteRune('"')
			case '\\':
				sb.WriteRune('\\')
			default:
				sb.WriteRune('\\')
				sb.WriteRune(escaped)
			}
		} else {
			sb.WriteRune(ch)
		}
	}
	return Token{Type: TokString, Val: sb.String(), Line: startLine, Col: startCol}
}

func (l *HCLLexer) readHeredoc() Token {
	startLine, startCol := l.line, l.col
	l.advance()
	l.advance()
	if l.peek() == '-' {
		l.advance()
	}
	var tagSb strings.Builder
	for l.pos < len(l.src) && isIdentPart(l.src[l.pos]) {
		tagSb.WriteRune(l.advance())
	}
	tag := tagSb.String()
	for l.pos < len(l.src) && l.src[l.pos] != '\n' {
		l.advance()
	}
	if l.pos < len(l.src) {
		l.advance()
	}
	var contentSb strings.Builder
	for l.pos < len(l.src) {
		lineStartPos := l.pos
		var lineSb strings.Builder
		for l.pos < len(l.src) && l.src[l.pos] != '\n' {
			lineSb.WriteRune(l.advance())
		}
		if l.pos < len(l.src) {
			l.advance()
		}
		trimmed := strings.TrimSpace(lineSb.String())
		if trimmed == tag {
			break
		}
		contentSb.WriteString(lineSb.String())
		contentSb.WriteRune('\n')
		_ = lineStartPos
	}
	return Token{Type: TokString, Val: contentSb.String(), Line: startLine, Col: startCol}
}

type HCLParser struct {
	lexer *HCLLexer
	tok   Token
}

func NewHCLParser(input string) *HCLParser {
	lex := NewHCLLexer(input)
	p := &HCLParser{lexer: lex}
	p.tok = lex.NextToken()
	return p
}

func (p *HCLParser) next() {
	p.tok = p.lexer.NextToken()
}

func (p *HCLParser) parseBody() (OrderedMap, error) {
	om := make(OrderedMap, 0)
	for p.tok.Type != TokEOF && !(p.tok.Type == TokSymbol && p.tok.Val == "}") {
		if p.tok.Type != TokIdent && p.tok.Type != TokString {
			return nil, fmt.Errorf("At %d:%d: illegal char", p.tok.Line, p.tok.Col)
		}
		key := p.tok.Val
		p.next()

		if p.tok.Type == TokSymbol && (p.tok.Val == "=" || p.tok.Val == ":") {
			p.next()
			val, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if objMap, isMap := val.(OrderedMap); isMap {
				val = []interface{}{objMap}
			}
			om = setOrUpdateMapKey(om, key, val)
		} else {
			var labels []string
			for p.tok.Type == TokString || p.tok.Type == TokIdent {
				labels = append(labels, p.tok.Val)
				p.next()
			}
			if p.tok.Type != TokSymbol || p.tok.Val != "{" {
				return nil, fmt.Errorf("At %d:%d: object expected closing RBRACE got: %s", p.tok.Line, p.tok.Col, p.tok.Val)
			}
			p.next()
			body, err := p.parseBody()
			if err != nil {
				return nil, err
			}
			if p.tok.Type != TokSymbol || p.tok.Val != "}" {
				return nil, fmt.Errorf("At %d:%d: object expected closing RBRACE got: EOF", p.tok.Line, p.tok.Col)
			}
			p.next()

			blockTree := buildBlockTree(labels, body)
			om = appendBlockToMap(om, key, blockTree)
		}
		if p.tok.Type == TokSymbol && p.tok.Val == "," {
			p.next()
		}
	}
	return om, nil
}

func buildBlockTree(labels []string, body OrderedMap) OrderedMap {
	if len(labels) == 0 {
		return body
	}
	return OrderedMap{
		MapItem{Key: labels[0], Value: []interface{}{buildBlockTree(labels[1:], body)}},
	}
}

func appendBlockToMap(om OrderedMap, key string, blockVal OrderedMap) OrderedMap {
	for i, item := range om {
		if item.Key == key {
			if arr, isArr := item.Value.([]interface{}); isArr {
				om[i].Value = append(arr, blockVal)
				return om
			}
		}
	}
	return append(om, MapItem{Key: key, Value: []interface{}{blockVal}})
}

func setOrUpdateMapKey(om OrderedMap, key string, val interface{}) OrderedMap {
	for i, item := range om {
		if item.Key == key {
			om[i].Value = val
			return om
		}
	}
	return append(om, MapItem{Key: key, Value: val})
}

func (p *HCLParser) parseExpr() (interface{}, error) {
	switch p.tok.Type {
	case TokString:
		v := p.tok.Val
		p.next()
		return v, nil
	case TokNumber:
		v := p.tok.Val
		p.next()
		if i, err := strconv.ParseInt(v, 10, 64); err == nil {
			return i, nil
		}
		if f, err := strconv.ParseFloat(v, 64); err == nil {
			return f, nil
		}
		return v, nil
	case TokIdent:
		v := p.tok.Val
		p.next()
		if v == "true" {
			return true, nil
		}
		if v == "false" {
			return false, nil
		}
		if v == "null" {
			return nil, nil
		}
		return v, nil
	case TokSymbol:
		if p.tok.Val == "[" {
			p.next()
			var arr []interface{}
			for p.tok.Type != TokEOF && !(p.tok.Type == TokSymbol && p.tok.Val == "]") {
				elem, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				arr = append(arr, elem)
				if p.tok.Type == TokSymbol && p.tok.Val == "," {
					p.next()
				}
			}
			if p.tok.Type == TokSymbol && p.tok.Val == "]" {
				p.next()
			}
			return arr, nil
		}
		if p.tok.Val == "{" {
			p.next()
			om, err := p.parseBody()
			if err != nil {
				return nil, err
			}
			if p.tok.Type == TokSymbol && p.tok.Val == "}" {
				p.next()
			}
			return om, nil
		}
	}
	return nil, fmt.Errorf("At %d:%d: unexpected token %s", p.tok.Line, p.tok.Col, p.tok.Val)
}

func convertInfNaNToStrings(v interface{}) interface{} {
	switch val := v.(type) {
	case float64:
		if math.IsInf(val, 1) {
			return "Infinity"
		}
		if math.IsInf(val, -1) {
			return "-Infinity"
		}
		if math.IsNaN(val) {
			return "NaN"
		}
		return val
	case OrderedMap:
		om := make(OrderedMap, len(val))
		for i, item := range val {
			om[i] = MapItem{Key: item.Key, Value: convertInfNaNToStrings(item.Value)}
		}
		return om
	case []interface{}:
		arr := make([]interface{}, len(val))
		for i, elem := range val {
			arr[i] = convertInfNaNToStrings(elem)
		}
		return arr
	default:
		return v
	}
}

func convertStringsToInfNaN(v interface{}) interface{} {
	switch val := v.(type) {
	case string:
		if val == "Infinity" {
			return math.Inf(1)
		}
		if val == "-Infinity" {
			return math.Inf(-1)
		}
		if val == "NaN" {
			return math.NaN()
		}
		return val
	case OrderedMap:
		om := make(OrderedMap, len(val))
		for i, item := range val {
			om[i] = MapItem{Key: item.Key, Value: convertStringsToInfNaN(item.Value)}
		}
		return om
	case []interface{}:
		arr := make([]interface{}, len(val))
		for i, elem := range val {
			arr[i] = convertStringsToInfNaN(elem)
		}
		return arr
	default:
		return v
	}
}

func handleInfNaNForJSON(v interface{}) interface{} {
	switch val := v.(type) {
	case float64:
		if math.IsInf(val, 1) {
			return math.MaxFloat64
		}
		if math.IsInf(val, -1) {
			return -math.MaxFloat64
		}
		if math.IsNaN(val) {
			return nil
		}
		return val
	case OrderedMap:
		om := make(OrderedMap, len(val))
		for i, item := range val {
			om[i] = MapItem{Key: item.Key, Value: handleInfNaNForJSON(item.Value)}
		}
		return om
	case []interface{}:
		arr := make([]interface{}, len(val))
		for i, elem := range val {
			arr[i] = handleInfNaNForJSON(elem)
		}
		return arr
	default:
		return v
	}
}

func parseKeysInMap(v interface{}) interface{} {
	switch val := v.(type) {
	case OrderedMap:
		om := make(OrderedMap, len(val))
		for i, item := range val {
			key := item.Key
			if keyStr, ok := key.(string); ok {
				var parsed interface{}
				if err := json.Unmarshal([]byte(keyStr), &parsed); err == nil {
					key = parsed
				}
			}
			om[i] = MapItem{
				Key:   key,
				Value: parseKeysInMap(item.Value),
			}
		}
		return om
	case []interface{}:
		arr := make([]interface{}, len(val))
		for i, elem := range val {
			arr[i] = parseKeysInMap(elem)
		}
		return arr
	default:
		return v
	}
}
